  v_env text := upper(btrim(coalesce(p_env, '')));
  v_kind text := upper(btrim(coalesce(p_entity_kind, '')));
  v_requested_hash text := nullif(btrim(coalesce(p_bank_details_hash, '')), '');

  v_now timestamptz := now();
  v_entity_exists boolean := false;
